const spirit_device_clip_t *spirit_device_clip(unsigned role, unsigned family, unsigned action)
{
    if (role >= 4) role = 0;
    if (family >= 3) family = 2;
    if (action >= 8) action = 0;
    return &clips[role][family][action];
}
const lv_image_dsc_t *spirit_device_frame(unsigned role, unsigned family, unsigned action, unsigned frame)
{
    const spirit_device_clip_t *clip = spirit_device_clip(role, family, action);
    return clip->frames[frame < 4 && clip->frames[frame] ? frame : 0];
}